<footer class="settings-savebar"><form method="post" action="<?=e(url('/vendedor/fiscal/integracao/token'))?>"><?=csrf_field()?><button class="button button--primary"><?=empty($credential)?'Gerar token':'Rotacionar token'?></button></form><?php if(!empty($credential['enabled'])&&empty($credential['revoked_at'])):?><form method="post" action="<?=e(url('/vendedor/fiscal/integracao/token/revogar'))?>"><?=csrf_field()?><button class="button button--secondary">Revogar token</button></form><?php endif;?></footer>
