<?php if(in_array((string)$d['status'],['awaiting_manual','awaiting_external'],true)):?><form enctype="multipart/form-data" method="post" action="<?=e(url('/vendedor/fiscal/integracao/documentos/'.(int)$d['seller_order_id'].'/registrar'))?>"><?=csrf_field()?><div class="settings-grid"><label class="settings-field">Número<input name="number" type="number" min="1" required></label><label class="settings-field">Série<input name="series" type="number" min="1" max="999" value="<?=e((string)($d['series']??1))?>" required></label><label class="settings-field">Chave<input name="access_key" maxlength="44" pattern="\d{44}" required></label><label class="settings-field">Protocolo<input name="protocol"></label><label class="settings-field">Referência externa<input name="external_reference"></label><label class="settings-field">XML<input type="file" name="xml" accept=".xml,application/xml,text/xml"></label><label class="settings-field">DANFE<input type="file" name="danfe" accept=".pdf,application/pdf"></label></div><button class="button button--secondary">Registrar NF-e</button></form><?php endif;?>
<?php if(in_array((string)$d['status'],['authorized','cancelled'],true)&&(!$d['xml_storage_path']||!$d['danfe_storage_path'])):?><form enctype="multipart/form-data" method="post" action="<?=e(url('/vendedor/fiscal/integracao/documentos/'.(int)$d['seller_order_id'].'/arquivos'))?>"><?=csrf_field()?><label>XML <input type="file" name="xml" accept=".xml,application/xml,text/xml"></label> <label>DANFE <input type="file" name="danfe" accept=".pdf,application/pdf"></label><button class="button button--secondary">Anexar arquivos</button></form><?php endif;?>
<?php if((string)$d['status']==='authorized'):?><form method="post" action="<?=e(url('/vendedor/fiscal/integracao/documentos/'.(int)$d['seller_order_id'].'/cancelar'))?>"><?=csrf_field()?><label>Motivo <input name="reason" minlength="15" maxlength="1000" required></label><label>Protocolo <input name="cancellation_protocol"></label><button class="button button--secondary">Registrar cancelamento</button></form><?php elseif((string)$d['status']==='cancelled'):?><small>Cancelada: <?=e((string)($d['cancellation_reason']??'motivo não informado'))?></small><?php endif;?>
</td></tr><?php endforeach;?></tbody></table></div></section>
